void preserved(const Scene &before,const Scene &after,const detail::SourceRestGraph &graph){for(const auto &part:graph.parts){const auto &a=before.object(part.object),&b=after.object(part.object);check(a.painted==b.painted&&a.material_bindings==b.material_bindings,"Source rest plan retains actual painting/material owners including real rigid accessories");if(part.original_skin<0){check(before.world_matrix(part.object).matrix()==after.world_matrix(part.object).matrix()&&a.deformation==b.deformation,"Real rigid current placement/morph is unchanged by REST pivot editing");continue;}auto old=a.deformation->skeleton->skin_matrices(a.deformation->pose),now=b.deformation->skeleton->skin_matrices(b.deformation->pose);for(size_t slot=0;slot<old.size();++slot){auto x=before.world_matrix(part.object)*AffineTransform(old[slot]),y=after.world_matrix(part.object)*AffineTransform(now[slot]);for(size_t k=0;k<16;++k)if(std::abs(x.matrix()[k]-y.matrix()[k])>2e-5)throw std::runtime_error("Per-skin independent actual WORLD bind/pose mismatch");}check(true,"Each source skin preserves its own old weighted-slot WORLD products without borrowing another IBM/pose");}}
